async function api(path, opts = {}){
  const sep = path.includes("?") ? "&" : "?";
  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
    headers: {"Content-Type":"application/json"}, ...opts
  });
  if(!res.ok){
    let msg = res.statusText;
    try { msg = (await res.json()).error || msg; } catch {}
    throw new Error(msg);
  }
  return res.json();
}
function showBlocked(msg){
  const app = document.getElementById("app");
  app.textContent = "";
  const p = document.createElement("p");
  p.style.cssText = "padding:24px;color:var(--bad)";
  p.textContent = "Cannot load the board: " + msg;
  app.append(p);
}
async function load(){
  try {
    REG = await api("/api/registry");
    applyDrafts();
    render();
  } catch(e){
    flash(e.message);
    if(!REG) showBlocked(e.message);
  }
}

// any failed write reloads from disk, so the board never shows a state that was not saved
async function write(path, payload, method = "POST"){
  let ok = true;
  try {
    const opts = {method};
    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
    await api(path, opts);
  } catch(e){
    ok = false;
    flash(e.message);
  }
  await load();          // load() handles its own errors, so a failed reload is never silent
  return ok;
}

