    for key in ("meta", "projects", "ideas"):
        if key not in data:
            problems.append(f"missing top-level key: {key}")
    ranks_seen: dict[str, set[int]] = {}
    for p in data.get("projects", []):
        name = p.get("name") or "<unnamed>"
        if not isinstance(p.get("name"), str) or not p.get("name"):
            problems.append("project with missing/empty name")
        if p.get("lane") not in LANES:
            problems.append(f"{name}: lane must be one of {sorted(LANES)}")
        if not isinstance(p.get("rank"), int) or p.get("rank", 0) < 1:
            problems.append(f"{name}: rank must be an int >= 1")
        if p.get("status") not in PROJECT_STATUSES:
            problems.append(f"{name}: status must be one of {sorted(PROJECT_STATUSES)}")
        if "stage" in p and p.get("stage") not in STAGES:
            problems.append(f"{name}: stage must be one of {STAGES}")
        for field in ("purpose", "next_action"):
            if not isinstance(p.get(field), str):
                problems.append(f"{name}: {field} must be a string")
        if p.get("status") == "active" and p.get("lane") in LANES and isinstance(p.get("rank"), int):
            lane_ranks = ranks_seen.setdefault(p["lane"], set())
            if p["rank"] in lane_ranks:
                problems.append(f"{name}: duplicate rank {p['rank']} in lane {p['lane']}")
            lane_ranks.add(p["rank"])
    for i in data.get("ideas", []):
        if not isinstance(i.get("pitch"), str) or not i.get("pitch"):
            problems.append("idea with missing/empty pitch")
        if i.get("status") not in IDEA_STATUSES:
            problems.append(f"idea '{i.get('pitch', '?')[:30]}': bad status")
    if problems:
        raise RegistryError("; ".join(problems))


def load_registry(path: Path) -> dict:
    if not path.exists():
        raise RegistryError(f"registry not found: {path}")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as e:
        raise RegistryError(f"registry unreadable: {e}") from e
    validate(data)
    return data


def save_registry(path: Path, data: dict) -> None:
    validate(data)
    if path.exists():
        shutil.copy2(path, path.with_suffix(path.suffix + ".bak"))
    payload = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(payload, encoding="utf-8")
    os.replace(tmp, path)          # atomic on the same filesystem


def add_idea(data: dict, pitch: str, source: str = "") -> dict:
    idea = {
        "captured_at": _dt.datetime.now().isoformat(timespec="seconds"),
        "pitch": pitch,
        "source": source,
        "status": "inbox",
    }
    data.setdefault("ideas", []).append(idea)
    return idea


def add_update(data: dict, name: str, note: str, next_action: str | None = None) -> dict:
    for p in data.get("projects", []):
        if p["name"].lower() == name.lower():
            p.setdefault("updates", []).append(
                {"date": _dt.date.today().isoformat(), "note": note}
            )
            if next_action:
                p["next_action"] = next_action
            p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            return p
    raise RegistryError(f"no project named '{name}'")


def set_stage(data: dict, name: str, stage: str) -> dict:
    if stage not in STAGES:
        raise RegistryError(f"stage must be one of {STAGES}")
    for p in data.get("projects", []):
        if p["name"].lower() == name.lower():
            p["stage"] = stage
            p.setdefault("updates", []).append(
                {"date": _dt.date.today().isoformat(), "note": f"stage → {stage}"}
            )
            p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            return p
    raise RegistryError(f"no project named '{name}'")


def main(argv: list[str] | None = None) -> int:
    registry_path = Path(__file__).resolve().parent / "portfolio.json"

    parser = argparse.ArgumentParser(prog="portfolio.py")
    subparsers = parser.add_subparsers(dest="command", required=True)

    idea_parser = subparsers.add_parser("add-idea")
    idea_parser.add_argument("pitch")
    idea_parser.add_argument("--source", default="")

    update_parser = subparsers.add_parser("add-update")
    update_parser.add_argument("name")
    update_parser.add_argument("note")
    update_parser.add_argument("--next-action", default=None)

    stage_parser = subparsers.add_parser("set-stage")
    stage_parser.add_argument("name")
    stage_parser.add_argument("stage")

    args = parser.parse_args(argv)

    try:
        data = load_registry(registry_path)
        if args.command == "add-idea":
            add_idea(data, args.pitch, source=args.source)
            save_registry(registry_path, data)
            inbox_count = sum(1 for i in data.get("ideas", []) if i.get("status") == "inbox")
            print(f"idea captured ({inbox_count} in inbox)")
        elif args.command == "add-update":
            add_update(data, args.name, args.note, next_action=args.next_action)
            save_registry(registry_path, data)
            print(f"updated {args.name}")
        elif args.command == "set-stage":
            set_stage(data, args.name, args.stage)
            save_registry(registry_path, data)
            print(f"stage set: {args.name} → {args.stage}")
    except RegistryError as e:
        print(f"[error] {e}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Local drag-and-drop board over portfolio.json.

Binds 127.0.0.1 only. A per-run token guards /api/*, and writes additionally
require a same-origin request, because any page in the browser can POST to a
localhost port.
"""
import argparse
import datetime as _dt
import http.server
import json
import secrets
import threading
import webbrowser
from pathlib import Path
from urllib.parse import urlparse, parse_qs, unquote

import board_ops
import portfolio
from portfolio import RegistryError

LOCK = threading.Lock()


class Handler(http.server.BaseHTTPRequestHandler):
    repo: Path = None
    token: str = ""
    undo: dict = None

    def log_message(self, *args):        # keep the terminal quiet
        pass

    # ---------- helpers ----------
    def _send(self, code, payload=None, body=None, ctype="application/json"):
        data = body if body is not None else json.dumps(payload or {}).encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def _authorised(self, parsed) -> bool:
        got = parse_qs(parsed.query).get("token", [""])[0]
        return secrets.compare_digest(got, self.token)

    def _same_origin(self) -> bool:
        origin = self.headers.get("Origin")
        if origin is None:
            return True                  # non-browser client, e.g. curl
        host = self.headers.get("Host", "")
        return origin in (f"http://{host}", f"https://{host}")

    def _load(self):
        return portfolio.load_registry(self.repo / "portfolio.json")

    def _save(self, data):
        portfolio.save_registry(self.repo / "portfolio.json", data)

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        return json.loads(self.rfile.read(length) or b"{}")

    # ---------- routes ----------
    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/":
            page = (self.repo / "board.html").read_bytes()
            return self._send(200, body=page, ctype="text/html; charset=utf-8")
        if not parsed.path.startswith("/api/"):
            return self._send(404, {"error": "not found"})
        if not self._authorised(parsed):
            return self._send(403, {"error": "bad or missing token"})
        if parsed.path == "/api/registry":
            data = self._load()
            data["today"] = _dt.date.today().isoformat()
            return self._send(200, data)
        return self._send(404, {"error": "not found"})

    def _mutate(self, fn):
        """Run fn(data), snapshot for undo, save. Returns the saved registry."""
        with LOCK:
            data = self._load()
            snapshot = json.loads(json.dumps(data))
            fn(data)
            self._save(data)
            type(self).undo = snapshot
            return data

    def do_POST(self):
        parsed = urlparse(self.path)
        if not self._authorised(parsed):
            return self._send(403, {"error": "bad or missing token"})
        if not self._same_origin():
            return self._send(403, {"error": "cross-origin write refused"})

        parts = [p for p in parsed.path.split("/") if p]     # ["api", ...]
        try:
            body = self._body()
        except json.JSONDecodeError:
            return self._send(400, {"error": "body is not valid JSON"})
        if not isinstance(body, dict):
            return self._send(400, {"error": "body must be a JSON object"})

        try:
            if parts == ["api", "move"]:
                data = self._mutate(lambda d: board_ops.reorder(
                    d, body["name"], body["lane"], body["stage"], int(body.get("position", 0))))
                lane = [{"name": p["name"], "rank": p["rank"], "stage": p.get("stage")}
                        for p in board_ops.live(data, body["lane"])]
                return self._send(200, {"ok": True, "lane": lane})

            if parts == ["api", "undo"]:
                with LOCK:
                    snapshot = type(self).undo
                    if snapshot is None:
                        return self._send(400, {"error": "nothing to undo"})
                    self._save(snapshot)
                    type(self).undo = None
                return self._send(200, {"ok": True})

            if len(parts) == 3 and parts[:2] == ["api", "project"]:
                name = unquote(parts[2])
                self._mutate(lambda d: board_ops.patch_project(
                    d, name,
                    status=body.get("status"),
                    purpose=body.get("purpose"),
                    next_action=body.get("next_action"),
                    note=body.get("note"),
                    today=_dt.date.today().isoformat()))
                return self._send(200, {"ok": True})

            if len(parts) == 4 and parts[:2] == ["api", "inbox"] and parts[3] == "promote":
                name = unquote(parts[2])
                self._mutate(lambda d: board_ops.promote(
                    d, name, body["lane"], body["stage"], int(body.get("position", 0)),
                    body.get("purpose", ""), body.get("next_action", "")))
                return self._send(200, {"ok": True})

        except RegistryError as e:
            return self._send(400, {"error": str(e)})
        except KeyError as e:
            return self._send(400, {"error": f"missing field: {e.args[0]}"})
        except (ValueError, TypeError, AttributeError) as e:
            return self._send(400, {"error": str(e)})

        return self._send(404, {"error": "not found"})

    def do_DELETE(self):
        parsed = urlparse(self.path)
        if not self._authorised(parsed):
            return self._send(403, {"error": "bad or missing token"})
        if not self._same_origin():
            return self._send(403, {"error": "cross-origin write refused"})
        parts = [p for p in parsed.path.split("/") if p]
        try:
            if len(parts) == 3 and parts[:2] == ["api", "project"]:
                name = unquote(parts[2])
                self._mutate(lambda d: board_ops.delete_project(d, name))
                return self._send(200, {"ok": True})
            if len(parts) == 3 and parts[:2] == ["api", "inbox"]:
                name = unquote(parts[2])
                self._mutate(lambda d: board_ops.delete_inbox(d, name))
                return self._send(200, {"ok": True})
        except RegistryError as e:
            return self._send(400, {"error": str(e)})
        return self._send(404, {"error": "not found"})


def make_server(repo: Path, token: str, port: int = 0) -> http.server.HTTPServer:
    handler = type("BoundHandler", (Handler,), {"repo": Path(repo), "token": token})
    return http.server.HTTPServer(("127.0.0.1", port), handler)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Local portfolio board")
    ap.add_argument("--repo", type=Path, default=Path(__file__).parent)
    ap.add_argument("--port", type=int, default=0)
    ap.add_argument("--no-open", action="store_true")
    args = ap.parse_args(argv)

    portfolio.load_registry(args.repo / "portfolio.json")   # refuse to start on a bad file

    token = secrets.token_urlsafe(16)
    srv = make_server(args.repo, token, args.port)
    url = f"http://127.0.0.1:{srv.server_address[1]}/?token={token}"
    print(f"board at {url}")
    print("ctrl-c to stop")
    if not args.no_open:
        webbrowser.open(url)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nstopped")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

